export const overlayCSS = "/* JUST-PR — Editorial Command Center */\n\n/* ─── Reset ─────────────────────────────────────────────────── */\n:host {\n  all: initial;\n  display: block;\n\n  /* ─── Color System (Pure Light) ─────────────────────── */\n  --bg:            #ffffff;\n  --bg-surface:    #f5f4f2;\n  --bg-raised:     #ece9e4;\n  --bg-hover:      #e3dfd8;\n  --bg-glass:      rgba(255, 255, 255, 0.97);\n\n  --bg-code:       #f8f7f5;\n  --bg-code-before:#fff8f8;\n  --bg-code-after: #f6fff9;\n\n  --border:        rgba(0, 0, 0, 0.09);\n  --border-mid:    rgba(0, 0, 0, 0.14);\n  --border-bright: rgba(0, 0, 0, 0.22);\n\n  /* Copper accent */\n  --copper:        #9a5216;\n  --copper-dim:    rgba(154, 82, 22, 0.08);\n  --copper-mid:    rgba(154, 82, 22, 0.18);\n  --copper-bright: rgba(154, 82, 22, 0.36);\n\n  /* Semantic colors */\n  --green:         #166534;\n  --green-dim:     rgba(22, 101, 52, 0.08);\n  --green-mid:     rgba(22, 101, 52, 0.18);\n\n  --red:           #991b1b;\n  --red-dim:       rgba(153, 27, 27, 0.07);\n  --red-mid:       rgba(153, 27, 27, 0.17);\n\n  --amber:         #92400e;\n  --amber-dim:     rgba(146, 64, 14, 0.08);\n  --amber-mid:     rgba(146, 64, 14, 0.18);\n\n  --yellow:        #713f12;\n  --yellow-dim:    rgba(113, 63, 18, 0.08);\n\n  /* Text — high contrast */\n  --text-primary:  #111110;\n  --text-secondary:#2e2a25;\n  --text-dim:      #635c54;\n  --text-ghost:    #a09890;\n\n  /* Legacy alias */\n  --navy:          #9a5216;\n  --navy-mid:      rgba(154, 82, 22, 0.12);\n  --navy-dim:      rgba(154, 82, 22, 0.06);\n\n  /* ─── Typography ─────────────────────────────────── */\n  --display: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Noto Sans\", Helvetica, Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\";\n  --ui:      -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"Noto Sans\", Helvetica, Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\";\n  --mono:    ui-monospace, SFMono-Regular, \"SF Mono\", Menlo, Consolas, \"Liberation Mono\", monospace;\n\n  /* ─── Layout ─────────────────────────────────────── */\n  --panel-width: 1080px;\n  --header-h:    52px;\n  --sp:          22px;\n  --radius:      6px;\n  --radius-lg:   10px;\n\n  /* ─── Motion ─────────────────────────────────────── */\n  --t:      160ms cubic-bezier(0.25, 0.46, 0.45, 0.94);\n  --t-slow: 320ms cubic-bezier(0.25, 0.46, 0.45, 0.94);\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\n/* ─── Toggle ────────────────────────────────────────────────── */\n#just-pr-toggle {\n  position: fixed;\n  top: 72px;\n  right: 0;\n  z-index: 2147483646;\n  pointer-events: auto;\n\n  writing-mode: vertical-rl;\n  text-orientation: mixed;\n  transform: rotate(180deg);\n\n  width: 30px;\n  padding: 16px 6px;\n\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-right: none;\n  border-radius: var(--radius) 0 0 var(--radius);\n\n  font-family: var(--mono);\n  font-size: 10px;\n  font-weight: 500;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  color: var(--text-dim);\n\n  cursor: pointer;\n  transition: all var(--t);\n  box-shadow: -3px 0 12px rgba(0,0,0,0.4);\n}\n\n#just-pr-toggle::before {\n  content: '';\n  position: absolute;\n  top: 0; left: 0; bottom: 0;\n  width: 2px;\n  background: var(--copper);\n  border-radius: var(--radius) 0 0 var(--radius);\n  opacity: 0;\n  transition: opacity var(--t);\n}\n\n#just-pr-toggle:hover {\n  color: var(--text-primary);\n  background: var(--bg-raised);\n  border-color: var(--border-mid);\n}\n\n#just-pr-toggle:hover::before,\n#just-pr-toggle.jp-active::before { opacity: 1; }\n\n#just-pr-toggle.jp-active {\n  color: var(--copper);\n  background: var(--bg-surface);\n}\n\n/* ─── Panel ─────────────────────────────────────────────────── */\n#just-pr-panel {\n  position: fixed;\n  top: 0; right: 0;\n  width: 100vw;\n  height: 100vh;\n  z-index: 2147483645;\n\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n\n  background: var(--bg);\n  border-left: 1px solid var(--border);\n  box-shadow: -4px 0 24px rgba(0,0,0,0.10), -1px 0 0 rgba(168,98,30,0.06);\n\n  transform: translateX(100%);\n  transition: transform var(--t-slow);\n}\n\n#just-pr-panel.jp-open {\n  transform: translateX(0);\n}\n\n/* ─── Resize Handle ─────────────────────────────────────────── */\n#just-pr-resize-handle {\n  position: absolute;\n  left: 0; top: 0; bottom: 0;\n  width: 4px;\n  cursor: ew-resize;\n  z-index: 10;\n  transition: background var(--t);\n}\n\n#just-pr-resize-handle:hover,\n#just-pr-resize-handle.jp-resizing {\n  background: var(--copper);\n  opacity: 0.5;\n}\n\n/* ─── Header ────────────────────────────────────────────────── */\n.jp-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: var(--header-h);\n  padding: 0 16px 0 20px;\n  flex-shrink: 0;\n  background: var(--bg-surface);\n  border-bottom: 1px solid var(--border);\n  position: relative;\n}\n\n.jp-header::after {\n  content: '';\n  position: absolute;\n  bottom: -1px; left: 0;\n  width: 40px; height: 1px;\n  background: var(--copper);\n  opacity: 0.6;\n}\n\n.jp-logo {\n  font-family: var(--display);\n  font-size: 17px;\n  font-weight: 400;\n  font-style: italic;\n  color: var(--text-primary);\n  letter-spacing: -0.01em;\n}\n\n.jp-logo-sub {\n  font-family: var(--mono);\n  font-style: normal;\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--copper);\n  margin-left: 8px;\n  vertical-align: middle;\n  opacity: 0.9;\n}\n\n.jp-header-right { display: flex; align-items: center; gap: 4px; }\n\n.jp-btn-icon {\n  width: 28px; height: 28px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 17px;\n  border: none;\n  border-radius: var(--radius);\n  background: transparent;\n  color: var(--text-dim);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-btn-icon:hover {\n  background: var(--bg-raised);\n  color: var(--text-primary);\n}\n\n/* ─── Progress Bar ──────────────────────────────────────────── */\n.jp-progress-bar {\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n  padding: 10px 20px;\n  background: var(--bg-surface);\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n  animation: jp-enter 200ms ease both;\n}\n\n.jp-progress-meta {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.jp-progress-step-name {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.06em;\n  color: var(--text-secondary);\n}\n\n.jp-progress-counter {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  letter-spacing: 0.06em;\n}\n\n.jp-progress-steps {\n  display: flex;\n  gap: 3px;\n}\n\n.jp-progress-step {\n  flex: 1;\n  height: 2px;\n  background: var(--bg-raised);\n  border-radius: 1px;\n  cursor: pointer;\n  transition: background var(--t);\n  position: relative;\n  overflow: hidden;\n}\n\n.jp-progress-step::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: var(--copper);\n  transform: scaleX(0);\n  transform-origin: left;\n  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n.jp-progress-step.jp-done::after { transform: scaleX(1); background: var(--copper); opacity: 0.5; }\n.jp-progress-step.jp-current::after { transform: scaleX(1); background: var(--copper); }\n.jp-progress-step:hover { background: var(--bg-hover); }\n\n.jp-progress-step-dot { display: none; }\n\n/* ─── Screen Container ──────────────────────────────────────── */\n.jp-screen {\n  flex: 1;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n\n/* ─── Idle Screen ───────────────────────────────────────────── */\n.jp-idle {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: flex-start;\n  padding: 48px var(--sp);\n  animation: jp-enter 250ms ease both;\n  position: relative;\n  overflow: hidden;\n}\n\n.jp-idle::before {\n  content: '';\n  position: absolute;\n  top: -120px; right: -60px;\n  width: 400px; height: 400px;\n  background: radial-gradient(circle, rgba(200,131,58,0.06) 0%, transparent 70%);\n  pointer-events: none;\n}\n\n.jp-idle-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.2em;\n  text-transform: uppercase;\n  color: var(--copper);\n  margin-bottom: 24px;\n}\n\n.jp-idle-badge::before {\n  content: '';\n  display: block;\n  width: 4px; height: 4px;\n  background: var(--copper);\n  border-radius: 50%;\n  animation: jp-pulse 2s ease infinite;\n}\n\n.jp-idle-heading {\n  font-family: var(--display);\n  font-size: 36px;\n  font-weight: 400;\n  font-style: italic;\n  line-height: 1.15;\n  color: var(--text-primary);\n  letter-spacing: -0.02em;\n  margin-bottom: 24px;\n}\n\n.jp-idle-url {\n  font-family: var(--mono);\n  font-size: 20px;\n  color: var(--text-dim);\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  padding: 8px 12px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  margin-bottom: 28px;\n  letter-spacing: 0.02em;\n}\n\n.jp-analyze-btn {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: #fff8f0;\n  background: var(--copper);\n  border: none;\n  border-radius: var(--radius);\n  padding: 13px 24px;\n  cursor: pointer;\n  transition: all var(--t);\n  position: relative;\n  overflow: hidden;\n}\n\n.jp-analyze-btn::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: rgba(255,255,255,0.1);\n  opacity: 0;\n  transition: opacity var(--t);\n}\n\n.jp-analyze-btn:hover::after { opacity: 1; }\n.jp-analyze-btn:active { transform: translateY(1px); }\n\n/* ─── Loading Screen ────────────────────────────────────────── */\n.jp-loading {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 20px;\n  padding: var(--sp);\n  animation: jp-enter 200ms ease both;\n}\n\n.jp-loading-mark {\n  position: relative;\n  width: 48px; height: 48px;\n  display: flex; align-items: center; justify-content: center;\n}\n\n.jp-loading-ring {\n  width: 40px; height: 40px;\n  border-radius: 50%;\n  border: 2px solid var(--bg-raised);\n  border-top-color: var(--copper);\n  animation: jp-spin 0.8s linear infinite;\n}\n\n.jp-loading-pct {\n  font-family: var(--display);\n  font-size: 52px;\n  font-weight: 400;\n  font-style: italic;\n  color: var(--text-primary);\n  letter-spacing: -0.03em;\n  line-height: 1;\n}\n\n.jp-loading-phase {\n  font-family: var(--mono);\n  font-size: 20px;\n  color: var(--text-dim);\n  letter-spacing: 0.06em;\n}\n\n.jp-loading-phase::after {\n  content: '';\n  animation: jp-dots 1.5s steps(4, end) infinite;\n}\n\n.jp-loading-steps {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  width: 220px;\n}\n\n.jp-loading-step {\n  font-family: var(--mono);\n  font-size: 14px;\n  letter-spacing: 0.06em;\n  color: var(--text-ghost);\n  line-height: 1.35;\n  padding: 6px 10px;\n  border-radius: 3px;\n  transition: all var(--t);\n  position: relative;\n  padding-left: 28px;\n}\n\n.jp-loading-step::before {\n  content: '○';\n  position: absolute;\n  left: 10px;\n  top: 50%;\n  transform: translateY(-50%);\n  font-size: 14px;\n  line-height: 1;\n}\n\n.jp-loading-step--done {\n  color: var(--green);\n  opacity: 0.7;\n}\n\n.jp-loading-step--done::before { content: '✓'; }\n\n.jp-loading-step--active {\n  color: var(--copper);\n  background: var(--copper-dim);\n}\n\n.jp-loading-step--active::before { content: '◉'; animation: jp-pulse 1s ease infinite; }\n\n.jp-loading-track {\n  width: 180px; height: 2px;\n  background: var(--bg-raised);\n  border-radius: 1px;\n  overflow: hidden;\n}\n\n.jp-loading-fill {\n  height: 100%;\n  background: var(--copper);\n  border-radius: 1px;\n  transition: width 500ms cubic-bezier(0.4, 0, 0.2, 1);\n  width: 0%;\n}\n\n/* ─── Overview Screen ───────────────────────────────────────── */\n.jp-overview {\n  flex: 1;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  scrollbar-width: thin;\n  scrollbar-color: var(--bg-raised) transparent;\n  animation: jp-enter 200ms ease both;\n}\n\n.jp-overview::-webkit-scrollbar { width: 4px; }\n.jp-overview::-webkit-scrollbar-thumb { background: var(--bg-raised); border-radius: 2px; }\n\n.jp-section {\n  padding: 20px var(--sp);\n  border-bottom: 1px solid var(--border);\n}\n\n.jp-section-label {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.22em;\n  text-transform: uppercase;\n  color: var(--text-ghost);\n  margin-bottom: 14px;\n}\n\n/* Risk Hero */\n.jp-risk-hero {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  margin-bottom: 14px;\n}\n\n.jp-risk-score {\n  font-family: var(--display);\n  font-size: 72px;\n  font-weight: 400;\n  font-style: italic;\n  line-height: 1;\n  letter-spacing: -0.04em;\n  transition: color 0.4s ease;\n}\n\n.jp-risk-score[data-level=\"low\"]      { color: var(--green); }\n.jp-risk-score[data-level=\"medium\"]   { color: var(--yellow); }\n.jp-risk-score[data-level=\"high\"]     { color: var(--amber); }\n.jp-risk-score[data-level=\"critical\"] { color: var(--red); }\n\n.jp-risk-aside {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.jp-risk-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  padding: 4px 9px;\n  border-radius: 3px;\n  border: 1px solid;\n}\n\n.jp-risk-badge-dot {\n  width: 4px; height: 4px;\n  border-radius: 50%;\n}\n\n.jp-risk-badge[data-level=\"low\"]      { color: var(--green);  border-color: var(--green-mid);  background: var(--green-dim); }\n.jp-risk-badge[data-level=\"medium\"]   { color: var(--yellow); border-color: var(--yellow-dim); background: var(--yellow-dim); }\n.jp-risk-badge[data-level=\"high\"]     { color: var(--amber);  border-color: var(--amber-mid);  background: var(--amber-dim); }\n.jp-risk-badge[data-level=\"critical\"] { color: var(--red);    border-color: var(--red-mid);    background: var(--red-dim); }\n\n.jp-risk-badge[data-level=\"low\"]      .jp-risk-badge-dot { background: var(--green); }\n.jp-risk-badge[data-level=\"medium\"]   .jp-risk-badge-dot { background: var(--yellow); }\n.jp-risk-badge[data-level=\"high\"]     .jp-risk-badge-dot { background: var(--amber); }\n.jp-risk-badge[data-level=\"critical\"] .jp-risk-badge-dot { background: var(--red); }\n\n.jp-risk-subtext {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  letter-spacing: 0.06em;\n}\n\n.jp-risk-track {\n  height: 2px;\n  background: var(--bg-raised);\n  border-radius: 1px;\n  overflow: hidden;\n}\n\n.jp-risk-fill {\n  height: 100%;\n  border-radius: 1px;\n  width: 0%;\n  transition: width 900ms cubic-bezier(0.4, 0, 0.2, 1) 80ms;\n}\n\n.jp-risk-fill[data-level=\"low\"]      { background: var(--green); }\n.jp-risk-fill[data-level=\"medium\"]   { background: var(--yellow); }\n.jp-risk-fill[data-level=\"high\"]     { background: var(--amber); }\n.jp-risk-fill[data-level=\"critical\"] { background: var(--red); }\n\n/* Summary */\n.jp-summary-text {\n  font-family: var(--ui);\n  font-size: 20px;\n  line-height: 1.7;\n  color: var(--text-secondary);\n}\n\n.jp-cursor {\n  display: inline-block;\n  width: 2px; height: 1em;\n  background: var(--copper);\n  margin-left: 2px;\n  vertical-align: text-bottom;\n  animation: jp-blink 0.9s step-end infinite;\n}\n\n.jp-cursor.jp-done { display: none; }\n\n/* Chips */\n.jp-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.jp-chip {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  padding: 4px 9px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  color: var(--text-secondary);\n  text-transform: uppercase;\n}\n\n/* Order list */\n.jp-order-list { display: flex; flex-direction: column; gap: 2px; }\n\n.jp-order-item {\n  display: grid;\n  grid-template-columns: 28px 22px 1fr auto;\n  align-items: center;\n  gap: 10px;\n  padding: 9px 10px;\n  border-radius: var(--radius);\n  cursor: pointer;\n  transition: background var(--t);\n  border: 1px solid transparent;\n}\n\n.jp-order-item:hover {\n  background: var(--bg-surface);\n  border-color: var(--border);\n}\n\n.jp-order-num {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  text-align: right;\n  letter-spacing: 0.06em;\n}\n\n.jp-order-icon { font-size: 20px; }\n.jp-order-label {\n  font-family: var(--ui);\n  font-size: 20px;\n  font-weight: 500;\n  color: var(--text-secondary);\n}\n\n.jp-order-item:hover .jp-order-label { color: var(--text-primary); }\n\n.jp-order-risk {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  padding: 2px 6px;\n  border-radius: 2px;\n}\n\n.jp-order-risk[data-level=\"low\"]      { color: var(--green);  background: var(--green-dim); }\n.jp-order-risk[data-level=\"medium\"]   { color: var(--yellow); background: var(--yellow-dim); }\n.jp-order-risk[data-level=\"high\"]     { color: var(--amber);  background: var(--amber-dim); }\n.jp-order-risk[data-level=\"critical\"] { color: var(--red);    background: var(--red-dim); }\n\n/* Start Button */\n.jp-start-btn-wrap {\n  padding: 16px var(--sp);\n  margin-top: auto;\n  background: linear-gradient(to top, var(--bg) 70%, transparent);\n  flex-shrink: 0;\n}\n\n.jp-start-btn {\n  width: 100%;\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: #fff8f0;\n  background: var(--copper);\n  border: none;\n  border-radius: var(--radius);\n  padding: 13px 24px;\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-start-btn:hover { opacity: 0.9; }\n.jp-start-btn:disabled { opacity: 0.3; cursor: not-allowed; }\n\n.jp-start-btn-count {\n  color: rgba(20,20,20,0.55);\n  font-weight: 400;\n}\n\n/* ─── Step Screen ───────────────────────────────────────────── */\n.jp-step {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  animation: jp-enter 180ms ease both;\n}\n\n.jp-step-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  padding: 16px 20px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n  background: var(--bg-surface);\n}\n\n.jp-step-rail-dot {\n  width: 8px; height: 8px;\n  border-radius: 50%;\n  flex-shrink: 0;\n  margin-top: 6px;\n  border: 2px solid;\n}\n\n.jp-step-rail-dot[data-level=\"low\"]      { border-color: var(--green);  background: var(--green-dim); }\n.jp-step-rail-dot[data-level=\"medium\"]   { border-color: var(--yellow); background: var(--yellow-dim); }\n.jp-step-rail-dot[data-level=\"high\"]     { border-color: var(--amber);  background: var(--amber-dim); }\n.jp-step-rail-dot[data-level=\"critical\"] { border-color: var(--red);    background: var(--red-dim); }\n\n.jp-step-header-text { flex: 1; min-width: 0; }\n\n.jp-step-eyebrow {\n  font-family: var(--mono);\n  font-size: 20px;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  color: var(--text-ghost);\n  margin-bottom: 5px;\n}\n\n.jp-step-title-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 6px;\n}\n\n.jp-step-icon { font-size: 20px; }\n\n.jp-step-title {\n  font-family: var(--display);\n  font-size: 20px;\n  font-weight: 400;\n  font-style: italic;\n  color: var(--text-primary);\n  letter-spacing: -0.01em;\n  flex: 1;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.jp-step-risk-pill {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  padding: 2px 7px;\n  border-radius: 3px;\n  flex-shrink: 0;\n  border: 1px solid;\n}\n\n.jp-step-risk-pill[data-level=\"low\"]      { color: var(--green);  background: var(--green-dim);  border-color: var(--green-mid); }\n.jp-step-risk-pill[data-level=\"medium\"]   { color: var(--yellow); background: var(--yellow-dim); border-color: var(--yellow-dim); }\n.jp-step-risk-pill[data-level=\"high\"]     { color: var(--amber);  background: var(--amber-dim);  border-color: var(--amber-mid); }\n.jp-step-risk-pill[data-level=\"critical\"] { color: var(--red);    background: var(--red-dim);    border-color: var(--red-mid); }\n\n.jp-step-header-summary {\n  font-family: var(--ui);\n  font-size: 17px;\n  line-height: 1.6;\n  color: var(--text-dim);\n  font-style: italic;\n}\n\n/* Step columns */\n.jp-step-cols {\n  display: grid;\n  grid-template-columns: 148px 1fr;\n  flex: 1;\n  overflow: hidden;\n  min-height: 0;\n}\n\n/* File navigator (left) */\n.jp-step-col-files {\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  border-right: 1px solid var(--border);\n  padding: 12px 8px;\n  background: var(--bg-surface);\n  scrollbar-width: thin;\n  scrollbar-color: var(--bg-raised) transparent;\n}\n\n.jp-col-label {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  color: var(--text-ghost);\n  padding: 4px 8px 10px;\n}\n\n.jp-file-group { margin-bottom: 12px; }\n\n.jp-file-group-name {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  color: var(--text-dim);\n  padding: 3px 8px 6px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  letter-spacing: 0.02em;\n}\n\n.jp-file-range-list { display: flex; flex-direction: column; gap: 1px; }\n\n.jp-file-range-btn {\n  width: 100%;\n  text-align: left;\n  background: transparent;\n  border: 1px solid transparent;\n  border-radius: var(--radius);\n  padding: 6px 8px;\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-file-range-btn:hover {\n  background: var(--bg-raised);\n  border-color: var(--border);\n}\n\n.jp-file-range-btn--active {\n  background: var(--copper-dim);\n  border-color: var(--copper-mid);\n}\n\n.jp-file-range-group {\n  font-family: var(--ui);\n  font-size: 20px;\n  color: var(--text-secondary);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  margin-bottom: 3px;\n}\n\n.jp-file-range-btn--active .jp-file-range-group { color: var(--copper); }\n\n.jp-file-range-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.jp-file-range-footer-right {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.jp-file-range-line {\n  font-family: var(--mono);\n  font-size: 20px;\n  color: var(--text-ghost);\n  letter-spacing: 0.04em;\n}\n\n.jp-file-range-risk {\n  width: 5px; height: 5px;\n  border-radius: 50%;\n}\n\n.jp-file-range-risk[data-level=\"low\"]      { background: var(--green); }\n.jp-file-range-risk[data-level=\"medium\"]   { background: var(--yellow); }\n.jp-file-range-risk[data-level=\"high\"]     { background: var(--amber); }\n.jp-file-range-risk[data-level=\"critical\"] { background: var(--red); }\n\n/* Diff view (center/right) */\n.jp-step-col-diffs {\n  flex: 1;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  scrollbar-width: thin;\n  scrollbar-color: var(--bg-raised) transparent;\n}\n\n.jp-step-col-diffs::-webkit-scrollbar { width: 3px; }\n.jp-step-col-diffs::-webkit-scrollbar-thumb { background: var(--bg-raised); }\n\n.jp-diff-focus { display: flex; flex-direction: column; flex: 1; }\n\n.jp-diff-card-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--border);\n  gap: 10px;\n  background: var(--bg-surface);\n}\n\n.jp-diff-card-meta { flex: 1; min-width: 0; }\n\n.jp-diff-card-title {\n  font-family: var(--ui);\n  font-size: 17px;\n  font-weight: 500;\n  color: var(--text-primary);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  margin-bottom: 2px;\n}\n\n.jp-diff-card-file {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  letter-spacing: 0.02em;\n}\n\n.jp-diff-card-diff {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  min-width: 0;\n  flex: 1;\n}\n\n.jp-diff-card-diff .jp-diff-col:first-child {\n  border-right: 1px solid var(--border);\n}\n\n.jp-diff-focus-summary {\n  font-family: var(--ui);\n  font-size: 17px;\n  line-height: 1.6;\n  color: var(--text-secondary);\n  font-style: italic;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--border);\n  background: rgba(200, 131, 58, 0.03);\n  border-left: 2px solid var(--copper);\n  border-left-width: 2px;\n}\n\n/* ─── Diff Columns ──────────────────────────────────────────── */\n.jp-diff-col {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  min-width: 0;\n}\n\n.jp-diff-col-header {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n\n.jp-diff-col--before .jp-diff-col-header {\n  color: var(--red);\n  background: rgba(153, 27, 27, 0.06);\n}\n\n.jp-diff-col--after .jp-diff-col-header {\n  color: var(--green);\n  background: rgba(22, 101, 52, 0.06);\n}\n\n.jp-diff-col--empty .jp-diff-col-header {\n  color: var(--text-ghost);\n  background: var(--bg-surface);\n}\n\n.jp-diff-code {\n  font-family: var(--mono);\n  font-size: 20px;\n  line-height: 1.65;\n  padding: 10px 10px;\n  overflow-x: auto;\n  white-space: pre;\n  word-break: normal;\n  color: var(--text-secondary);\n  background: var(--bg-code);\n  flex: 1;\n  scrollbar-width: thin;\n  scrollbar-color: var(--bg-raised) transparent;\n}\n\n.jp-diff-col--before .jp-diff-code { background: var(--bg-code-before); }\n.jp-diff-col--after  .jp-diff-code { background: var(--bg-code-after); }\n.jp-diff-col--empty  .jp-diff-code { background: var(--bg-code); color: var(--text-ghost); font-style: italic; }\n.jp-diff-col--empty  .jp-diff-code {\n  color: var(--text-ghost);\n  font-style: italic;\n}\n\n/* Syntax highlight tokens — light background */\n.hljs-keyword  { color: #7c3aed; }\n.hljs-string   { color: #166534; }\n.hljs-number   { color: #92400e; }\n.hljs-comment  { color: var(--text-ghost); font-style: italic; }\n.hljs-function, .hljs-title { color: var(--copper); font-weight: 500; }\n.hljs-variable, .hljs-attr  { color: #1e40af; }\n.hljs-meta     { color: #6d28d9; }\n.hljs-type     { color: #0369a1; }\n.hljs-built_in { color: #0f766e; }\n.hljs-operator { color: var(--text-dim); }\n\n/* Existing review comments on a snippet */\n.jp-existing-comments {\n  padding: 10px 14px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.jp-existing-comments-label {\n  font-family: var(--mono);\n  font-size: 16px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  color: var(--text-ghost);\n  text-transform: uppercase;\n  margin-bottom: 2px;\n}\n\n.jp-existing-comment {\n  padding: 8px 10px;\n  background: var(--bg-inset);\n  border: 1px solid var(--border);\n  border-left: 3px solid var(--copper-mid);\n  border-radius: var(--radius);\n}\n\n.jp-existing-comment-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 4px;\n}\n\n.jp-existing-comment-author {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 600;\n  color: var(--text-secondary);\n}\n\n.jp-existing-comment-line {\n  font-family: var(--mono);\n  font-size: 16px;\n  color: var(--text-ghost);\n}\n\n.jp-existing-comment-body {\n  font-size: 19px;\n  line-height: 1.55;\n  color: var(--text-primary);\n}\n\n.jp-existing-comment-body pre,\n.jp-existing-comment-body code {\n  font-family: var(--mono);\n  font-size: 17px;\n  background: var(--bg-surface);\n  border-radius: 3px;\n  padding: 1px 4px;\n}\n\n/* Per-snippet note row */\n.jp-diff-card-note-wrap {\n  padding: 10px 14px;\n  border-top: 1px solid var(--border);\n  background: var(--bg-surface);\n}\n\n.jp-snippet-comment-btn {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  padding: 4px 10px;\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  background: transparent;\n  color: var(--text-ghost);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-snippet-comment-btn:hover {\n  border-color: var(--copper-mid);\n  color: var(--copper);\n  background: var(--copper-dim);\n}\n\n/* ─── Feedback / Findings ───────────────────────────────────── */\n.jp-feedback-card {\n  border-top: 1px solid var(--border);\n  background: var(--bg);\n}\n\n.jp-feedback-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--border);\n}\n\n.jp-feedback-title {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--text-dim);\n}\n\n.jp-feedback-meta {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  letter-spacing: 0.04em;\n}\n\n.jp-feedback-list { display: flex; flex-direction: column; }\n\n.jp-feedback-list .jp-finding-card {\n  border-radius: 0;\n  border-bottom: 1px solid var(--border);\n}\n\n.jp-feedback-list .jp-finding-card:last-child { border-bottom: none; }\n\n.jp-finding-card {\n  padding: 12px 14px;\n  background: var(--bg);\n  transition: background var(--t);\n}\n\n.jp-finding-card:hover { background: var(--bg-surface); }\n\n.jp-finding-card--critical {\n  background: rgba(212, 91, 91, 0.04);\n  border-left: 2px solid var(--red);\n}\n\n.jp-finding-row {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.jp-finding-text {\n  font-family: var(--ui);\n  font-size: 17px;\n  line-height: 1.6;\n  color: var(--text-secondary);\n  flex: 1;\n}\n\n.jp-finding-card--critical .jp-finding-text { color: var(--text-primary); }\n\n.jp-finding-action-label {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--red);\n  padding: 2px 6px;\n  border: 1px solid var(--red-mid);\n  border-radius: 3px;\n  background: var(--red-dim);\n  flex-shrink: 0;\n  margin-top: 2px;\n}\n\n.jp-finding-btns {\n  display: flex;\n  gap: 4px;\n}\n\n.jp-finding-btn {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.06em;\n  padding: 3px 9px;\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  background: transparent;\n  color: var(--text-ghost);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-finding-btn:hover {\n  border-color: var(--border-bright);\n  color: var(--text-secondary);\n  background: var(--bg-raised);\n}\n\n.jp-finding-btn--discuss {\n  border-color: var(--amber-mid);\n  color: var(--amber);\n  background: var(--amber-dim);\n}\n\n.jp-finding-btn--active {\n  border-color: var(--border-mid);\n  color: var(--text-dim);\n  background: var(--bg-raised);\n}\n\n.jp-finding-card--resolved {\n  opacity: 0.4;\n}\n\n.jp-finding-card--resolved .jp-finding-text {\n  text-decoration: line-through;\n}\n\n.jp-finding-card--ignored { opacity: 0.22; }\n\n.jp-findings-empty {\n  padding: 14px;\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n  font-style: italic;\n}\n\n/* Section note */\n.jp-section-note-wrap { padding: 10px 14px; }\n\n.jp-section-comment-btn {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  padding: 4px 10px;\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  background: transparent;\n  color: var(--text-ghost);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-section-comment-btn:hover {\n  border-color: var(--copper-mid);\n  color: var(--copper);\n  background: var(--copper-dim);\n}\n\n/* ─── Step Navigation ───────────────────────────────────────── */\n.jp-step-nav {\n  display: flex;\n  gap: 8px;\n  padding: 12px 16px;\n  border-top: 1px solid var(--border);\n  flex-shrink: 0;\n  background: var(--bg-surface);\n}\n\n.jp-nav-btn {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  padding: 9px 16px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  background: transparent;\n  color: var(--text-dim);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-nav-btn:hover {\n  border-color: var(--border-bright);\n  color: var(--text-primary);\n  background: var(--bg-raised);\n}\n\n.jp-nav-btn.jp-primary {\n  flex: 1;\n  background: var(--copper);\n  border-color: var(--copper);\n  color: #fff8f0;\n}\n\n.jp-nav-btn.jp-primary:hover { opacity: 0.88; }\n\n/* ─── Comment Components ────────────────────────────────────── */\n.jp-comment-box {\n  padding: 10px 14px;\n  border-top: 1px solid var(--border);\n  background: var(--bg-surface);\n  animation: jp-enter 120ms ease both;\n}\n\n.jp-comment-textarea {\n  width: 100%;\n  min-height: 72px;\n  resize: vertical;\n  font-family: var(--mono);\n  font-size: 20px;\n  line-height: 1.6;\n  letter-spacing: 0.02em;\n  color: var(--text-primary);\n  background: var(--bg-raised);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 8px 10px;\n  outline: none;\n  transition: border-color var(--t);\n}\n\n.jp-comment-textarea::placeholder { color: var(--text-ghost); }\n.jp-comment-textarea:focus { border-color: var(--copper); }\n\n.jp-comment-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 6px;\n  margin-top: 8px;\n}\n\n.jp-comment-cancel {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  padding: 5px 12px;\n  border: 1px solid var(--border);\n  border-radius: 3px;\n  background: transparent;\n  color: var(--text-ghost);\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-comment-cancel:hover {\n  border-color: var(--border-bright);\n  color: var(--text-secondary);\n}\n\n.jp-comment-save {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  padding: 5px 14px;\n  border: none;\n  border-radius: 3px;\n  background: var(--copper);\n  color: #fff8f0;\n  cursor: pointer;\n  transition: all var(--t);\n}\n\n.jp-comment-save:hover { opacity: 0.85; }\n\n.jp-comment-note {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  padding: 9px 12px;\n  background: var(--copper-dim);\n  border: 1px solid var(--copper-mid);\n  border-radius: var(--radius);\n  animation: jp-enter 120ms ease both;\n}\n\n.jp-comment-note-text {\n  flex: 1;\n  font-family: var(--mono);\n  font-size: 20px;\n  line-height: 1.6;\n  color: var(--text-secondary);\n  word-break: break-word;\n}\n\n.jp-comment-note-del {\n  flex-shrink: 0;\n  font-size: 20px;\n  border: none;\n  background: transparent;\n  color: var(--text-ghost);\n  cursor: pointer;\n  transition: color var(--t);\n  padding: 1px 3px;\n}\n\n.jp-comment-note-del:hover { color: var(--red); }\n\n/* ─── Snippet (legacy, used in older layout) ───────────────── */\n.jp-snippet {\n  border-bottom: 1px solid var(--border);\n  background: var(--bg);\n}\n\n.jp-snippet-file {\n  display: flex;\n  align-items: center;\n  padding: 8px 14px;\n  border-bottom: 1px solid var(--border);\n  background: var(--bg-surface);\n  gap: 8px;\n}\n\n.jp-snippet-file-name {\n  flex: 1;\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-dim);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.jp-snippet-line {\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-ghost);\n}\n\n.jp-snippet-explanation {\n  padding: 10px 14px;\n  font-family: var(--ui);\n  font-size: 17px;\n  line-height: 1.65;\n  color: var(--text-secondary);\n}\n\n.jp-diff {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n}\n\n.jp-diff .jp-diff-col:first-child { border-right: 1px solid var(--border); }\n\n/* ─── Decision Screen ───────────────────────────────────────── */\n.jp-decision {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  animation: jp-enter 200ms ease both;\n  position: relative;\n}\n\n.jp-decision-rail {\n  position: absolute;\n  left: 0; top: 0; bottom: 0;\n  width: 3px;\n  background: linear-gradient(to bottom, var(--copper) 0%, transparent 100%);\n  opacity: 0.6;\n}\n\n.jp-decision-header {\n  padding: var(--sp) var(--sp) 16px calc(var(--sp) + 8px);\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n}\n\n.jp-decision-eyebrow {\n  font-family: var(--mono);\n  font-size: 20px;\n  letter-spacing: 0.22em;\n  text-transform: uppercase;\n  color: var(--text-ghost);\n  margin-bottom: 6px;\n}\n\n.jp-decision-title {\n  font-family: var(--display);\n  font-size: 24px;\n  font-weight: 400;\n  font-style: italic;\n  color: var(--text-primary);\n  letter-spacing: -0.02em;\n}\n\n.jp-decision-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: var(--sp) var(--sp) var(--sp) calc(var(--sp) + 8px);\n  scrollbar-width: thin;\n  scrollbar-color: var(--bg-raised) transparent;\n}\n\n.jp-decision-body::-webkit-scrollbar { width: 3px; }\n.jp-decision-body::-webkit-scrollbar-thumb { background: var(--bg-raised); }\n\n/* AI Recommendation Card */\n.jp-rec-card {\n  display: flex;\n  align-items: flex-start;\n  gap: 14px;\n  padding: 16px 18px;\n  border-radius: var(--radius);\n  margin-bottom: 22px;\n  border-left: 3px solid;\n}\n\n.jp-rec-card[data-action=\"approve\"]         { border-color: var(--green);  background: var(--green-dim); }\n.jp-rec-card[data-action=\"request_changes\"] { border-color: var(--red);    background: var(--red-dim); }\n.jp-rec-card[data-action=\"needs_review\"]    { border-color: var(--amber);  background: var(--amber-dim); }\n\n.jp-rec-icon { font-size: 20px; flex-shrink: 0; margin-top: 1px; }\n.jp-rec-content { flex: 1; }\n\n.jp-rec-title {\n  font-family: var(--mono);\n  font-size: 17px;\n  font-weight: 500;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  margin-bottom: 6px;\n}\n\n.jp-rec-card[data-action=\"approve\"]         .jp-rec-title { color: var(--green); }\n.jp-rec-card[data-action=\"request_changes\"] .jp-rec-title { color: var(--red); }\n.jp-rec-card[data-action=\"needs_review\"]    .jp-rec-title { color: var(--amber); }\n\n.jp-rec-reason {\n  font-family: var(--ui);\n  font-size: 17px;\n  line-height: 1.65;\n  color: var(--text-secondary);\n}\n\n/* Decision Picker */\n.jp-sections-label {\n  font-family: var(--mono);\n  font-size: 20px;\n  letter-spacing: 0.22em;\n  text-transform: uppercase;\n  color: var(--text-ghost);\n  margin-bottom: 8px;\n}\n\n.jp-decision-picker {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  margin-bottom: 4px;\n}\n\n.jp-decision-pick-btn {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 12px 14px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  background: var(--bg-surface);\n  cursor: pointer;\n  text-align: left;\n  transition: all var(--t);\n  position: relative;\n  overflow: hidden;\n}\n\n.jp-decision-pick-btn::before {\n  content: '';\n  position: absolute;\n  left: 0; top: 0; bottom: 0;\n  width: 3px;\n  background: var(--border-mid);\n  transition: background var(--t);\n}\n\n.jp-decision-pick-btn:hover {\n  border-color: var(--border-bright);\n  background: var(--bg-raised);\n}\n\n.jp-decision-pick-btn--active[data-value=\"APPROVE\"]::before         { background: var(--green); }\n.jp-decision-pick-btn--active[data-value=\"REQUEST_CHANGES\"]::before { background: var(--red); }\n.jp-decision-pick-btn--active[data-value=\"COMMENT\"]::before         { background: var(--copper); }\n\n.jp-decision-pick-btn--active[data-value=\"APPROVE\"] {\n  border-color: var(--green-mid);\n  background: var(--green-dim);\n}\n\n.jp-decision-pick-btn--active[data-value=\"REQUEST_CHANGES\"] {\n  border-color: var(--red-mid);\n  background: var(--red-dim);\n}\n\n.jp-decision-pick-btn--active[data-value=\"COMMENT\"] {\n  border-color: var(--copper-mid);\n  background: var(--copper-dim);\n}\n\n.jp-decision-pick-label {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.08em;\n  color: var(--text-secondary);\n  min-width: 130px;\n}\n\n.jp-decision-pick-btn--active[data-value=\"APPROVE\"]         .jp-decision-pick-label { color: var(--green); }\n.jp-decision-pick-btn--active[data-value=\"REQUEST_CHANGES\"] .jp-decision-pick-label { color: var(--red); }\n.jp-decision-pick-btn--active[data-value=\"COMMENT\"]         .jp-decision-pick-label { color: var(--copper); }\n\n.jp-decision-pick-desc {\n  font-family: var(--ui);\n  font-size: 20px;\n  color: var(--text-ghost);\n}\n\n/* Sections list */\n.jp-flag-row {\n  display: grid;\n  grid-template-columns: 22px 1fr auto;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 12px;\n  font-size: 20px;\n  color: var(--text-secondary);\n  border-radius: var(--radius);\n  cursor: pointer;\n  transition: background var(--t);\n  border: 1px solid transparent;\n}\n\n.jp-flag-row:hover {\n  background: var(--bg-surface);\n  border-color: var(--border);\n  color: var(--text-primary);\n}\n\n.jp-flag-icon { font-size: 20px; text-align: center; }\n\n.jp-flag-name {\n  font-family: var(--ui);\n  font-size: 20px;\n  font-weight: 500;\n}\n\n.jp-flag-risk {\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  padding: 2px 6px;\n  border-radius: 2px;\n}\n\n.jp-flag-risk[data-level=\"low\"]      { color: var(--green);  background: var(--green-dim); }\n.jp-flag-risk[data-level=\"medium\"]   { color: var(--yellow); background: var(--yellow-dim); }\n.jp-flag-risk[data-level=\"high\"]     { color: var(--amber);  background: var(--amber-dim); }\n.jp-flag-risk[data-level=\"critical\"] { color: var(--red);    background: var(--red-dim); }\n\n/* Comment summary */\n.jp-comment-summary {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-top: 6px;\n  padding: 8px 12px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-dim);\n  letter-spacing: 0.04em;\n}\n\n.jp-comment-summary::before {\n  content: '◈';\n  font-size: 20px;\n  color: var(--copper);\n  opacity: 0.7;\n}\n\n/* Decision Footer */\n.jp-decision-footer {\n  flex-shrink: 0;\n  padding: 14px var(--sp) 14px calc(var(--sp) + 8px);\n  border-top: 1px solid var(--border);\n  background: var(--bg-surface);\n}\n\n/* Submit button */\n.jp-submit-review-btn {\n  display: block;\n  width: 100%;\n  margin-top: 12px;\n  padding: 12px 20px;\n  background: var(--copper);\n  color: #fff8f0;\n  border: none;\n  border-radius: var(--radius);\n  font-family: var(--mono);\n  font-size: 20px;\n  font-weight: 500;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  cursor: pointer;\n  transition: all var(--t);\n  position: relative;\n  overflow: hidden;\n}\n\n.jp-submit-review-btn::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: rgba(255,255,255,0.12);\n  opacity: 0;\n  transition: opacity var(--t);\n}\n\n.jp-submit-review-btn:hover::after { opacity: 1; }\n.jp-submit-review-btn:disabled {\n  opacity: 0.3;\n  cursor: not-allowed;\n}\n\n.jp-submit-review-status {\n  margin-top: 8px;\n  font-family: var(--mono);\n  font-size: 17px;\n  color: var(--text-dim);\n  text-align: center;\n  letter-spacing: 0.04em;\n}\n\n.jp-submit-review-status--ok  { color: var(--green); }\n.jp-submit-review-status--err { color: var(--red); }\n\n/* ─── Markdown Rendering ────────────────────────────────────── */\n.jp-md p { margin: 0 0 0.6em; }\n.jp-md p:last-child { margin-bottom: 0; }\n.jp-md strong { font-weight: 600; color: var(--text-primary); }\n.jp-md em { font-style: italic; }\n.jp-md code {\n  font-family: var(--mono);\n  font-size: 0.9em;\n  background: var(--bg-raised);\n  border: 1px solid var(--border-mid);\n  padding: 1px 5px;\n  border-radius: 3px;\n  color: var(--copper);\n}\n\n.jp-md pre {\n  font-family: var(--mono);\n  font-size: 20px;\n  background: var(--bg-raised);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 10px 12px;\n  overflow-x: auto;\n  margin: 0.4em 0;\n}\n\n.jp-md pre code {\n  background: none;\n  border: none;\n  padding: 0;\n  font-size: 1em;\n  color: var(--text-secondary);\n}\n\n.jp-md ul, .jp-md ol {\n  padding-left: 1.4em;\n  margin: 0 0 0.6em;\n}\n\n.jp-md li {\n  margin-bottom: 0.3em;\n  color: var(--text-secondary);\n  font-size: 0.92em;\n}\n\n.jp-md h1, .jp-md h2, .jp-md h3 {\n  font-family: var(--display);\n  font-style: italic;\n  color: var(--text-primary);\n  margin: 0.8em 0 0.4em;\n  letter-spacing: -0.01em;\n}\n\n.jp-md h1 { font-size: 1.3em; }\n.jp-md h2 { font-size: 1.15em; }\n.jp-md h3 { font-size: 1.05em; }\n\n.jp-md blockquote {\n  border-left: 2px solid var(--copper);\n  padding: 4px 12px;\n  margin: 0.5em 0;\n  background: var(--copper-dim);\n  border-radius: 0 var(--radius) var(--radius) 0;\n}\n\n.jp-md blockquote p { color: var(--text-secondary); }\n\n.jp-md a {\n  color: var(--copper);\n  text-decoration: underline;\n  text-decoration-color: var(--copper-mid);\n  text-underline-offset: 2px;\n}\n\n.jp-md a:hover { opacity: 0.8; }\n\n/* ─── Error ─────────────────────────────────────────────────── */\n.jp-error {\n  margin: 20px;\n  padding: 14px 14px 14px 16px;\n  border-left: 3px solid var(--red);\n  background: var(--red-dim);\n  font-family: var(--mono);\n  font-size: 20px;\n  line-height: 1.65;\n  color: var(--red);\n  border-radius: 0 var(--radius) var(--radius) 0;\n}\n\n.jp-error-label {\n  font-size: 20px;\n  letter-spacing: 0.2em;\n  text-transform: uppercase;\n  margin-bottom: 5px;\n  opacity: 0.6;\n}\n\n/* ─── GitHub Typography Overrides ───────────────────────────── */\n#just-pr-toggle,\n#just-pr-panel {\n  font-family: var(--ui);\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n#just-pr-panel * {\n  font-family: inherit;\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n#just-pr-panel .jp-logo,\n#just-pr-panel .jp-logo-sub,\n#just-pr-panel .jp-idle-heading,\n#just-pr-panel .jp-step-title,\n#just-pr-panel .jp-decision-title,\n#just-pr-panel .jp-loading-pct,\n#just-pr-panel .jp-risk-score {\n  font-style: normal;\n}\n\n#just-pr-panel .jp-logo { font-size: 16px; font-weight: 600; }\n#just-pr-panel .jp-logo-sub { font-size: 12px; letter-spacing: 0.08em; }\n#just-pr-panel .jp-idle-heading { font-size: 22px; line-height: 1.3; }\n#just-pr-panel .jp-decision-title { font-size: 20px; line-height: 1.35; }\n#just-pr-panel .jp-loading-pct { font-size: 34px; line-height: 1; }\n#just-pr-panel .jp-risk-score { font-size: 42px; line-height: 1; }\n\n#just-pr-panel .jp-section-label,\n#just-pr-panel .jp-col-label,\n#just-pr-panel .jp-step-eyebrow,\n#just-pr-panel .jp-decision-eyebrow,\n#just-pr-panel .jp-sections-label {\n  font-size: 12px;\n  letter-spacing: 0.08em;\n}\n\n#just-pr-panel .jp-progress-step-name,\n#just-pr-panel .jp-order-label,\n#just-pr-panel .jp-step-title,\n#just-pr-panel .jp-flag-name {\n  font-size: 15px;\n  font-weight: 600;\n}\n\n#just-pr-panel .jp-analyze-btn,\n#just-pr-panel .jp-start-btn,\n#just-pr-panel .jp-submit-review-btn,\n#just-pr-panel .jp-nav-btn,\n#just-pr-panel .jp-decision-pick-label,\n#just-pr-panel .jp-step-risk-pill,\n#just-pr-panel .jp-order-risk,\n#just-pr-panel .jp-flag-risk {\n  font-size: 12px;\n  letter-spacing: 0.06em;\n}\n\n#just-pr-panel .jp-diff-code,\n#just-pr-panel .jp-md pre,\n#just-pr-panel .jp-comment-textarea,\n#just-pr-panel .jp-comment-note-text {\n  font-family: var(--mono);\n  font-size: 12px;\n  line-height: 1.45;\n}\n\n/* ─── Mockup V3 Step Layout ─────────────────────────────────── */\n#just-pr-panel {\n  background: #f8fafc;\n}\n\n.jp-progress-bar {\n  display: none;\n}\n\n.jp-step {\n  background: #f1f5f9;\n  padding: 12px;\n  gap: 12px;\n  min-height: 0;\n}\n\n.jp-step-topbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background: #ffffff;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  padding: 10px 14px;\n  flex-shrink: 0;\n}\n\n.jp-step-topbar-left {\n  min-width: 0;\n}\n\n.jp-step-topbar-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: #0f172a;\n}\n\n.jp-step-topbar-subtitle {\n  margin-top: 2px;\n  font-size: 12px;\n  color: #64748b;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.jp-step-topbar-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.jp-step-topbar-btn {\n  border: 1px solid #e2e8f0;\n  background: #ffffff;\n  color: #334155;\n  border-radius: 8px;\n  font-size: 12px;\n  font-weight: 500;\n  padding: 7px 12px;\n  cursor: pointer;\n  transition: background var(--t), border-color var(--t), color var(--t);\n}\n\n.jp-step-topbar-btn:hover {\n  background: #f8fafc;\n  border-color: #cbd5e1;\n}\n\n.jp-step-topbar-btn:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.jp-step-topbar-btn-primary {\n  background: #0f172a;\n  color: #ffffff;\n  border-color: #0f172a;\n}\n\n.jp-step-topbar-btn-primary:hover {\n  background: #1e293b;\n  border-color: #1e293b;\n}\n\n.jp-step-header {\n  display: none;\n}\n\n.jp-step-cols {\n  display: grid;\n  grid-template-columns: 220px 1fr;\n  gap: 12px;\n  flex: 1;\n  overflow: hidden;\n  min-height: 0;\n}\n\n.jp-step-col-files {\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #ffffff;\n  padding: 12px;\n}\n\n.jp-col-label {\n  font-size: 11px;\n  letter-spacing: 0.08em;\n  color: #64748b;\n  padding: 0;\n  margin-bottom: 8px;\n}\n\n.jp-file-tree {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.jp-file-group-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  min-width: 0;\n}\n\n.jp-file-feedback-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 2px 6px;\n  border-radius: 999px;\n  border: 1px solid #fcd34d;\n  background: #fffbeb;\n  color: #b45309;\n  font-size: 10px;\n  font-weight: 700;\n  line-height: 1;\n  flex-shrink: 0;\n}\n\n.jp-file-feedback-icon {\n  font-size: 10px;\n  line-height: 1;\n}\n\n.jp-file-feedback-count {\n  min-width: 10px;\n  text-align: center;\n}\n\n.jp-tree-dir-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 2px 0;\n  color: #64748b;\n}\n\n.jp-tree-dir-caret {\n  font-size: 10px;\n  color: #94a3b8;\n  line-height: 1;\n}\n\n.jp-tree-dir-name {\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.jp-file-group--tree {\n  margin-bottom: 0;\n}\n\n.jp-file-group-name {\n  font-size: 12px;\n  font-weight: 600;\n  color: #334155;\n  padding: 2px 0 6px;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.jp-file-range-list {\n  border-left: 1px solid #e2e8f0;\n  padding-left: 8px;\n  gap: 6px;\n}\n\n.jp-file-range-btn {\n  border-radius: 10px;\n  border: 1px solid transparent;\n  background: #f8fafc;\n  padding: 8px 10px;\n}\n\n.jp-file-range-btn:hover {\n  border-color: #cbd5e1;\n  filter: saturate(1.04) brightness(0.99);\n}\n\n.jp-file-range-btn--active {\n  border-color: #f59e0b;\n  box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.15);\n}\n\n.jp-file-range-btn[data-level=\"low\"] {\n  background: #ecfdf5;\n  border-color: #a7f3d0;\n}\n\n.jp-file-range-btn[data-level=\"medium\"] {\n  background: #fffbeb;\n  border-color: #fde68a;\n}\n\n.jp-file-range-btn[data-level=\"high\"] {\n  background: #fff7ed;\n  border-color: #fdba74;\n}\n\n.jp-file-range-btn[data-level=\"critical\"] {\n  background: #fef2f2;\n  border-color: #fecaca;\n}\n\n.jp-file-range-btn--active[data-level=\"low\"] {\n  border-color: #34d399;\n}\n\n.jp-file-range-btn--active[data-level=\"medium\"] {\n  border-color: #f59e0b;\n}\n\n.jp-file-range-btn--active[data-level=\"high\"] {\n  border-color: #fb923c;\n}\n\n.jp-file-range-btn--active[data-level=\"critical\"] {\n  border-color: #f87171;\n}\n\n.jp-file-range-group {\n  font-size: 12px;\n  font-weight: 600;\n  color: #1e293b;\n}\n\n.jp-file-range-line {\n  font-size: 11px;\n  color: #64748b;\n}\n\n.jp-step-col-diffs {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  min-height: 0;\n  overflow-y: auto;\n  overflow-x: hidden;\n}\n\n.jp-step-context-card {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 10px;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #ffffff;\n  padding: 12px 14px;\n}\n\n.jp-step-context-title {\n  font-size: 14px;\n  font-weight: 600;\n  color: #0f172a;\n}\n\n.jp-step-context-copy {\n  margin-top: 4px;\n  font-size: 13px;\n  color: #475569;\n}\n\n.jp-step-context-impact {\n  border-radius: 999px;\n  border: 1px solid #e2e8f0;\n  background: #f8fafc;\n  color: #64748b;\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: capitalize;\n  padding: 5px 10px;\n  white-space: nowrap;\n}\n\n.jp-step-context-impact[data-level=\"critical\"],\n.jp-step-context-impact[data-level=\"high\"] {\n  border-color: #fecaca;\n  background: #fef2f2;\n  color: #b91c1c;\n}\n\n.jp-step-context-impact[data-level=\"medium\"] {\n  border-color: #fde68a;\n  background: #fffbeb;\n  color: #b45309;\n}\n\n.jp-step-context-impact[data-level=\"low\"] {\n  border-color: #a7f3d0;\n  background: #ecfdf5;\n  color: #047857;\n}\n\n.jp-diff-focus {\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  overflow: hidden;\n  background: #ffffff;\n  display: flex;\n  flex-direction: column;\n  flex: 0 0 auto;\n  min-height: 0;\n}\n\n.jp-diff-card-header {\n  border-bottom: 1px solid #e2e8f0;\n  background: #ffffff;\n}\n\n.jp-diff-card-title {\n  font-size: 20px;\n  font-weight: 600;\n  color: #0f172a;\n}\n\n.jp-diff-card-file {\n  font-size: 12px;\n  color: #64748b;\n}\n\n.jp-diff-focus-summary {\n  font-style: normal;\n  font-size: 13px;\n  color: #475569;\n  border-bottom: 1px solid #e2e8f0;\n  border-left: none;\n  background: #ffffff;\n}\n\n.jp-diff-card-diff {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1px;\n  background: #e2e8f0;\n  min-height: 0;\n}\n\n.jp-diff-col {\n  min-height: 0;\n}\n\n.jp-diff-col--before .jp-diff-col-header {\n  background: #fef2f2;\n  border-bottom-color: #fecaca;\n}\n\n.jp-diff-col--after .jp-diff-col-header {\n  background: #ecfdf5;\n  border-bottom-color: #a7f3d0;\n}\n\n.jp-diff-code-wrap {\n  display: flex;\n  overflow: visible;\n}\n\n.jp-diff-gutter {\n  font-family: var(--mono);\n  font-size: 12px;\n  line-height: 1.6;\n  padding: 10px 8px 10px 10px;\n  color: #94a3b8;\n  text-align: right;\n  user-select: none;\n  flex-shrink: 0;\n  border-right: 1px solid #e2e8f0;\n  background: inherit;\n  white-space: pre;\n  min-width: 36px;\n}\n\n.jp-diff-col--before .jp-diff-gutter { background: #fff5f5; border-right-color: #fecaca; }\n.jp-diff-col--after  .jp-diff-gutter { background: #f0fdf4; border-right-color: #a7f3d0; }\n\n.jp-diff-code {\n  height: auto;\n  font-size: 12px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1e293b;\n  min-height: 0;\n  overflow: visible;\n  flex: 1;\n  padding: 10px;\n  white-space: pre-wrap;\n  word-break: break-all;\n}\n\n.jp-feedback-container {\n  flex-shrink: 0;\n  min-height: 0;\n  max-height: 40%;\n  overflow: auto;\n}\n\n.jp-feedback-container:empty {\n  display: none;\n}\n\n.jp-diff-col--before .jp-diff-code {\n  background: #fff5f5;\n}\n\n.jp-diff-col--after .jp-diff-code {\n  background: #f0fdf4;\n}\n\n.jp-feedback-card {\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #ffffff;\n  overflow: hidden;\n}\n\n.jp-feedback-header {\n  border-bottom: 1px solid #e2e8f0;\n  background: #ffffff;\n}\n\n.jp-feedback-title {\n  font-family: var(--ui);\n  text-transform: none;\n  letter-spacing: 0;\n  font-size: 14px;\n  font-weight: 600;\n  color: #0f172a;\n}\n\n.jp-feedback-meta {\n  font-size: 12px;\n  color: #64748b;\n}\n\n.jp-feedback-list {\n  gap: 8px;\n  padding: 10px;\n  background: #ffffff;\n}\n\n.jp-feedback-list .jp-finding-card {\n  border: 1px solid #e2e8f0;\n  border-radius: 10px;\n  margin: 0;\n}\n\n.jp-feedback-list .jp-finding-card:last-child {\n  border-bottom: 1px solid #e2e8f0;\n}\n\n.jp-finding-card {\n  padding: 10px;\n}\n\n.jp-finding-card[data-kind=\"action-required\"] {\n  border-color: #fecaca;\n  background: #fef2f2;\n}\n\n.jp-finding-card[data-kind=\"question\"] {\n  border-color: #fde68a;\n  background: #fffbeb;\n}\n\n.jp-finding-card[data-kind=\"nit\"] {\n  border-color: #e2e8f0;\n  background: #ffffff;\n}\n\n.jp-finding-row {\n  flex-direction: column;\n  gap: 6px;\n  margin-bottom: 8px;\n}\n\n.jp-finding-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.jp-finding-kind {\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: #64748b;\n}\n\n.jp-finding-kind--action {\n  color: #b91c1c;\n}\n\n.jp-finding-badge-blocking {\n  border-radius: 999px;\n  background: #fee2e2;\n  color: #b91c1c;\n  padding: 2px 8px;\n  font-size: 11px;\n  font-weight: 600;\n}\n\n.jp-finding-text {\n  font-size: 14px;\n  line-height: 1.5;\n  color: #1e293b;\n}\n\n.jp-finding-btn {\n  border-radius: 8px;\n  padding: 5px 10px;\n  font-size: 12px;\n  letter-spacing: 0;\n}\n\n.jp-finding-btn:hover {\n  background: #f8fafc;\n}\n\n/* ─── Keyframes ─────────────────────────────────────────────── */\n@keyframes jp-spin {\n  to { transform: rotate(360deg); }\n}\n\n@keyframes jp-dots {\n  0%   { content: ''; }\n  25%  { content: '.'; }\n  50%  { content: '..'; }\n  75%  { content: '...'; }\n  100% { content: ''; }\n}\n\n@keyframes jp-blink {\n  0%, 100% { opacity: 1; }\n  50%       { opacity: 0; }\n}\n\n@keyframes jp-pulse {\n  0%, 100% { opacity: 1; }\n  50%       { opacity: 0.4; }\n}\n\n@keyframes jp-enter {\n  from { opacity: 0; transform: translateY(8px); }\n  to   { opacity: 1; transform: translateY(0); }\n}\n";
